    {t="C", q=6133, n="The Ranger Lord's Behest", pn="A mando do lorde patrulheiro", lvl=60, req=54, xp=6600, m=1423, x=46.69, y=13.18, ot="i", objs={{n="Pathstrider", p="Trilheiro", m=1423, x=46.69, y=13.18},{n="Ranger", p="Patrulheiro", m=1423, x=44.68, y=12.55},{n="Woodsman", p="Mateiro", m=1423, x=46.93, y=13.19},{n="Quel'Thalas Registry", p="Arquivos de Quel'Thalas", m=1423, x=45.27, y=12.7}}, obj="Travel to the northern borders of the Eastern Plaguelands and recover the Quel'Thalas Registry. The item is somewhere in the Quel'Lithien lodge.  You must also slay 8 Rangers, 8 Pathstriders, and 8 Woodsmen.", pobj="Vá à fronteira norte das Terras Pestilentas Orientais e recupere os Arquivos de Quel'Thalas em algum lugar do Abrigo Quel'Lithien.  Você também precisa matar 8 Patrulheiros, 8 Trilheiros e 8 Mateiros."},
    {t="C", q=6024, n="Hameya's Plea", pn="A súplica de Hameya", lvl=60, req=54, xp=6600, cc=1, m=1423, x=61.96, y=11.11, ot="i", obj="Kill Infiltrator Hameya. Use his key on the Mound of Dirt behind the Undercroft.", pobj="Mate o Infiltrador Hameya. Use a chave dele no Monturo de Terra atrás da Chácara Secreta."},
    {t="C", q=5845, n="Of Lost Honor", pn="Da honra perdida", lvl=58, req=52, xp=6200, m=1423, x=62.53, y=26.81, ot="i", obj="Travel to Northdale, in the northeastern region of the Eastern Plaguelands, and recover the Symbol of Lost Honor. Return to Tirion Fordring upon completion of your objective.", pobj="Viaje para o Vilarejo do Norte, na região nordeste das Terras Pestilentas Orientais, e recupere o Símbolo da Honra Perdida. Fale novamente com Tirion Fordring ao completar seu objetivo."},
    {t="C", q=9136, n="Savage Flora", pn="Flora selvagem", lvl=60, req=55, xp=6600, cc=30, m=1449, x=66.96, y=30.14, ot="i", obj="Rayne at Light's Hope Chapel in the Eastern Plaguelands wants 30 Savage Fronds.", pobj="Rayne, baseada na Capela Esperança da Luz, nas Terras Pestilentas Orientais, quer 30 Frondes Selvagens.", f={"coleta","drop","long"}},
    {t="C", q=9085, n="Shadows of Doom", pn="Sombra da Perdição", lvl=60, req=50, m=1423, x=64.85, y=45.93, ot="k", ahead={{q=9153, n="Under the Shadow", pn="Sob a sombra", i="Necrotic Rune", ip="Runa Necrótica", c=10}}, obj="Go to a summoning circle and kill a Shadow of Doom, then return to Commander Thomas Helleran at Light's Hope Chapel in Eastern Plaguelands.", pobj="Vá para um círculo de evocação e mate uma Sombra da Perdição. Em seguida, fale novamente com o Comandante Tomás Helleran na Capela Esperança da Luz, que fica nas Terras Pestilentas Orientais.", f={"elite"}},
    {t="C", q=9153, n="Under the Shadow", pn="Sob a sombra", lvl=60, req=50, cc=10, m=1423, x=64.85, y=45.93, ot="i", obj="Check your map to find an area under Scourge attack. Go there and damage a necropolis by defeating the Scourge around them. Return 10 of their Necrotic Runes to Commander Thomas Helleran at Light's Hope Chapel in the Eastern Plaguelands.", pobj="Verifique seu mapa para encontrar uma região sob ataque do Flagelo. Vá até lá e derrote os membros do Flagelo em torno da necrópole, a fim de danificá-la. Em seguida, entregue 10 Runas Necróticas para o Comandante Tomás Helleran na Capela Esperança da Luz, que fica nas Terras Pestilentas Orientais.", f={"coleta","drop"}},
