    {t="C", q=9237, n="Glacial Cloak", pn="Manto glacial", lvl=60, req=60, cc=15, m=1423, x=53.36, y=65.99, ot="i", ahead={{q=9229, n="The Fate of Ramaladni", pn="O destino de Ramaladni", i="Fate of Ramaladni", ip="Destino de Ramaladni", c=1, qi=true},{q=9230, n="Ramaladni's Icy Grasp", pn="O toque frio de Ramaladni", i="Blue Sapphire", ip="Safira Azul", c=1}}, objs={{n="Essence of Water", p="Essência da Água", m=1423, x=53.36, y=65.99},{n="Ironweb Spider Silk", p="Seda de Aranha Ferroteia", m=1422, x=62.71, y=50.32}}, obj="Craftsman Wilhelm at Light's Hope Chapel in the Eastern Plaguelands wants 5 Frozen Runes, 4 Bolts of Runecloth, 2 Essences of Water, 4 Ironweb Spider Silks and 200 gold. You must also be of Exalted reputation with the Argent Dawn.", pobj="O Artesão Wilhelm, da Capela Esperança da Luz, que fica nas Terras Pestilentas Orientais, quer 5 Runas Congeladas, 4 Peças de Runatrama, 2 Essências da Água, 4 Sedas de Aranha Ferroteia e 200 de ouro. Também é preciso ter a reputação de Exaltado com a Aurora Argêntea.", f={"coleta","drop"}},
    {t="C", q=9665, n="Bolstering Our Defenses", pn="Reforçando nossas defesas", lvl=60, req=55, xp=6600, m=1423, x=34.09, y=64.1, ot="k", objs={{n="<TXT>Crown Guard Capture Quest Doodad", m=1423, x=34.09, y=64.1},{n="<TXT>Eastwall Capture Quest Doodad", m=1423, x=59.04, y=39.41},{n="<TXT>Northpass Capture Quest Doodad", m=1423, x=49.25, y=18.2},{n="<TXT>Plaguewood Capture Quest Doodad", m=1423, x=18.16, y=25.06}}, obj="Capture Crown Guard Tower, Eastwall Tower, Northpass Tower and Plaguewood Tower in the Eastern Plaguelands, then return to Emmisary Gormok at Light's Hope Chapel.", pobj="Capture a Torre da Coroa, a Torre da Muralha Leste, a Torre do Passo Norte e a Torre do Bosque Pestilento, nas Terras Pestilentas Orientais, depois fale novamente com o Emissário Gormok, na Capela Esperança da Luz."},
    {t="C", q=5212, n="The Flesh Does Not Lie", pn="A carne não mente", lvl=60, req=55, xp=6600, cc=10, ot="i", ahead={{q=5263, n="Above and Beyond", pn="Acima e além", i="Head of Baron Rivendare", ip="Cabeça do Barão Rivendare", c=1, qi=true},{q=6163, n="Ramstein", pn="Ramstein", i="Head of Ramstein the Gorger", ip="Cabeça de Ramstein, o Devorador", c=1, qi=true}}, obj="Recover 10 Plagued Flesh Samples from Stratholme and return them to Betina Bigglezink. You suspect that any creature in Stratholme would have said flesh sample.", pobj="Recupere 20 Amostras de Carne Infectada de Stratholme e leve-as para Betina Bigozinco. Você desconfia que qualquer criatura em Stratholme poderia ter essa amostra de carne.", f={"coleta","drop"}},
    {t="C", q=5214, n="The Great Ezra Grimm", pn="O grande Ezra Carranca", lvl=60, req=55, xp=8300, cc=1, ot="i", obj="Find Ezra Grimm's smoke shop in Stratholme and recover a box of Grimm's Premium Tobacco. Return to Smokey LaRue when the job is done.", pobj="Encontre a tabacaria de Ezra Carranca em Stratholme e recolha uma caixa do Tabaco da Lata do Carranca. Fale novamente com Leandro Leonardo depois que tiver terminado o serviço."},
    {t="C", q=5243, n="Houses of the Holy", pn="Casas do sagrado", lvl=60, req=55, xp=6600, ot="i", obj="Travel to Stratholme, in the north. Search the supply crates that litter the city and recover 5 Stratholme Holy Water. Return to Leonid Barthalomew the Revered when you have collected enough of the blessed fluid.", pobj="Viaje para Stratholme, ao norte. Procure os caixotes de suprimentos que cobrem a cidade e recupere 5 Águas Bentas de Stratholme. Fale novamente com Leonid Bartolomeu, o Venerado, quando coletar fluido abençoado suficiente."},
    {t="C", q=5251, n="The Archivist", pn="O arquivista", lvl=60, req=55, xp=8300, ot="k", obj="Travel to Stratholme and find Archivist Galford of the Scarlet Crusade. Destroy him and burn down the Scarlet Archive.", pobj="Viaje até Stratholme e encontre o Arquivista Galford da Cruzada Escarlate. Destrua-o e queime o Arquivo Escarlate.", f={"elite"}},
    {t="C", q=5263, n="Above and Beyond", pn="Acima e além", lvl=60, req=55, xp=8300, cc=1, ot="i", ahead={{q=5212, n="The Flesh Does Not Lie", pn="A carne não mente", i="Plagued Flesh Sample", ip="Amostra de Carne Infectada", c=10, qi=true}}, obj="Venture to Stratholme and destroy Baron Rivendare. Take his head and return to Duke Nicholas Zverenhoff. ", pobj="Desbrave Stratholme e destrua o Barão Rivendare. Corte sua cabeça e leve-a de volta para o Duque Nicolau Zverenhoff."},
    {t="C", q=9033, n="Echoes of War", pn="Ecos da Guerra", lvl=60, req=60, xp=9950, ot="k", ahead={{q=9229, n="The Fate of Ramaladni", pn="O destino de Ramaladni", i="Fate of Ramaladni", ip="Destino de Ramaladni", c=1, qi=true},{q=9237, n="Glacial Cloak", pn="Manto glacial", i="Ironweb Spider Silk", ip="Seda de Aranha Ferroteia", c=5}}, obj="Commander Eligor Dawnbringer at Light's Hope Chapel in the Eastern Plaguelands wants you to slay 5 Living Monstrosities, 5 Stoneskin Gargoyles, 8 Deathknight Captains and 3 Venom Stalkers.", pobj="O Comandante Eligor Alvorada, na Capela Esperança da Luz, que fica nas Terras Pestilentas Orientais, quer que você mate 5 Monstruosidades Vivas, 5 Gárgulas Litopele, 8 Capitães Cavaleiros da Morte e 3 Espreitadoras Peçonhentas.", f={"elite"}},
